const inner = require("./inner.js");
const atLoad = module.parent;
exports.atLoad = typeof module.parent;
exports.parent = () => typeof module.parent;
exports.parentFilename = () => String(module.parent && module.parent.filename);
exports.sameParentAsAtLoad = () => module.parent === atLoad;
exports.children = () => module.children.length + " " + typeof module.children[0] + " " + (inner.parent() === module);
exports.paths = () => module.paths.length > 0;
exports.cached = () => require.cache[module.filename] === module;
